function readItems(n) {
  try { return $(n).all().map(i => i.json); } catch(e) { return []; }
}
function extractData(items) {
  return items.flatMap(function(item) {
    var pages = item.pages || [item];
    return pages.flatMap(function(p) {
      var d = p.data !== undefined ? p.data : p;
      return Array.isArray(d) ? d : (d && typeof d === 'object' ? [d] : []);
    });
  });
}

var flows       = extractData(readItems('Pack Flows'));
var tags        = extractData(readItems('Pack Tags'));
var pageInfoArr = extractData(readItems('Pack Page Info'));
var widgets     = extractData(readItems('Pack Widgets'));

return [{
  json: {
    page_info: pageInfoArr[0] || {},
    flows:     flows,
    tags:      tags,
    widgets:   widgets,
    _metadata: {
      exported_at: new Date().toISOString(),
      source: 'ManyChat API v2',
      counts: {
        flows:   flows.length,
        tags:    tags.length,
        widgets: widgets.length
      }
    }
  }
}];

var d    = $input.first().json;
var meta = d._metadata;
var pi   = d.page_info;
var SEP  = '─'.repeat(54);
var SEP2 = '═'.repeat(54);
var lines = [];

lines.push(SEP2);
lines.push('  MANYCHAT SNAPSHOT — VENTTUR');
lines.push('  Exportado: ' + meta.exported_at);
lines.push(SEP2);
lines.push('');

lines.push('RESUMEN');
lines.push(SEP);
lines.push('  flows:   ' + meta.counts.flows);
lines.push('  tags:    ' + meta.counts.tags);
lines.push('  widgets: ' + meta.counts.widgets);
lines.push('');

lines.push('CUENTA');
lines.push(SEP);
lines.push('  id:       ' + (pi.id || 'N/A'));
lines.push('  name:     ' + (pi.name || 'N/A'));
lines.push('  username: ' + (pi.username || 'N/A'));
lines.push('  timezone: ' + (pi.timezone || 'N/A'));
lines.push('');

lines.push('FLOWS (' + d.flows.length + ')');
lines.push(SEP);
d.flows.forEach(function(f) {
  lines.push('  ns:     ' + (f.ns || f.id || 'N/A'));
  lines.push('  name:   ' + (f.name || '(sin nombre)'));
  lines.push('  status: ' + (f.status || 'N/A'));
  lines.push('');
});

lines.push('TAGS (' + d.tags.length + ')');
lines.push(SEP);
d.tags.forEach(function(t) {
  lines.push('  [' + (t.id || 'N/A') + '] ' + (t.name || 'N/A'));
});
lines.push('');

lines.push('WIDGETS / GROWTH TOOLS (' + d.widgets.length + ')');
lines.push(SEP);
d.widgets.forEach(function(w) {
  lines.push('  [' + (w.id || 'N/A') + '] ' + (w.name || '(sin nombre)') + ' — ' + (w.type || 'N/A'));
});
lines.push('');

lines.push(SEP2);
lines.push('RAW JSON');
lines.push(SEP2);
lines.push(JSON.stringify(d, null, 2));

var txt = lines.join('\n');

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(txt, 'utf-8'),
  'manychat-venttur-snapshot.txt',
  'text/plain'
);

return [{ json: { filename: 'manychat-venttur-snapshot.txt' }, binary: { data: binaryData } }];
